import unittest
from slug import slugify


class HiddenSlugTest(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(slugify("Hello, World!"), "hello-world")

    def test_runs_collapse(self):
        self.assertEqual(slugify("a  --  b"), "a-b")

    def test_accents(self):
        self.assertEqual(slugify("Ni\u00f1o \u00dcber caf\u00e9"), "nino-uber-cafe")

    def test_edges_trimmed(self):
        self.assertEqual(slugify("  --Title--  "), "title")

    def test_empty(self):
        self.assertEqual(slugify(""), "untitled")
        self.assertEqual(slugify("!!!"), "untitled")

    def test_truncation_has_no_trailing_hyphen(self):
        text = "word " * 20
        result = slugify(text)
        self.assertLessEqual(len(result), 40)
        self.assertFalse(result.endswith("-"))
        self.assertTrue(result.startswith("word-word"))

    def test_exact_cut_on_hyphen(self):
        self.assertEqual(slugify("a" * 39 + " b"), "a" * 39)


if __name__ == "__main__":
    unittest.main()

